def backfill_providers(apps: Any, schema_editor: Any) -> None:
    """Preserve the provider identity of pre-existing external conversations."""
    connection_model = apps.get_model("bloomerp", "IMConnection")
    for connection in connection_model.objects.using(
        schema_editor.connection.alias
    ).all():
        for name in ("IMConversation", "IMIdentity"):
            apps.get_model("bloomerp", name).objects.using(
                schema_editor.connection.alias
            ).filter(connection_id=connection.pk).update(
                provider_key=connection.provider
            )


